    public function priorities(Request $request)
    {
        \App\Modules\Integration\Support\DomainApiInput::validate($request, ['q' => ['sometimes', 'string', 'max:255'], 'is_active' => ['sometimes', 'boolean']]);
        $query = \App\Modules\Ticket\Models\TicketPriority::query()->withCount('tickets');
        if ($request->filled('q')) {
            $query->where('name', 'like', '%'.$request->input('q').'%');
        }
        if ($request->has('is_active')) {
            $query->where('is_active', $request->boolean('is_active'));
        }

        return \App\Modules\Ticket\Resources\Api\V1\TicketPriorityResource::collection($query->orderBy('level')->orderBy('id')->paginate(DomainApiRead::pageSize($request))->withQueryString());
    }

